function norm(s) { return (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }

const DB = (() => {
    const NOME = 'il-mio-calendario';
    const CHIAVE_LS = 'imc-records';
    let idb = null;
    let modo = 'mem';
    let mem = {};
    function apriIdb() {
        return new Promise((ok, ko) => {
            const rq = indexedDB.open(NOME, 1);
            rq.onupgradeneeded = () => { rq.result.createObjectStore('records', { keyPath: 'id' }); };
            rq.onsuccess = () => ok(rq.result);
            rq.onerror = () => ko(rq.error);
            rq.onblocked = () => ko(new Error('bloccato'));
        });
    }
    function scriviLs() {
        try {
            localStorage.setItem(CHIAVE_LS, JSON.stringify(Object.values(mem)));
        }
        catch (_) { }
    }
    return {
        get modo() { return modo; },
        async apri() {
            try {
                idb = await apriIdb();
                modo = 'idb';
                return await new Promise((ok, ko) => {
                    const rq = idb.transaction('records').objectStore('records').getAll();
                    rq.onsuccess = () => ok(rq.result);
                    rq.onerror = () => ko(rq.error);
                });
            }
            catch (_) {
                try {
                    const txt = localStorage.getItem(CHIAVE_LS);
                    modo = 'ls';
                    const arr = txt ? JSON.parse(txt) : [];
                    for (const r of arr)
                        mem[r.id] = r;
                    return arr;
                }
                catch (_e) {
                    modo = 'mem';
                    return [];
                }
            }
        },
        salva(recs) {
            if (modo === 'idb' && idb) {
                return new Promise((ok, ko) => {
                    const tx = idb.transaction('records', 'readwrite');
                    const st = tx.objectStore('records');
                    for (const r of recs)
                        st.put(r);
                    tx.oncomplete = () => ok();
                    tx.onerror = () => ko(tx.error);
                    tx.onabort = () => ko(tx.error || new Error('scrittura annullata (spazio esaurito?)'));
                });
            }
            for (const r of recs)
                mem[r.id] = r;
            if (modo === 'ls')
                scriviLs();
            return Promise.resolve();
        },
        rimuovi(ids) {
            if (!ids.length)
                return Promise.resolve();
            if (modo === 'idb' && idb) {
                return new Promise((ok, ko) => {
                    const tx = idb.transaction('records', 'readwrite'), st = tx.objectStore('records');
                    for (const id of ids)
                        st.delete(id);
                    tx.oncomplete = () => ok();
                    tx.onerror = () => ko(tx.error);
                    tx.onabort = () => ko(tx.error || new Error('rimozione annullata'));
                });
            }
            for (const id of ids)
                delete mem[id];
            if (modo === 'ls')
                scriviLs();
            return Promise.resolve();
        },
    };
})();

function predefiniti() {
    return [
        { id: 'impostazioni', type: 'impostazioni', updatedAt: 1, tema: 'auto', accento: '#6c8cff', vistaIniziale: 'oggi', widgetNascosti: ['nota', 'tabelle', 'chiusura'] },
        { id: 'cat-studio', type: 'categoria', updatedAt: 1, nome: 'Studio', colore: '#6c8cff', visibile: true, ordine: 0 },
        { id: 'cat-personale', type: 'categoria', updatedAt: 1, nome: 'Personale', colore: '#2fbf8f', visibile: true, ordine: 1 },
        { id: 'cat-salute', type: 'categoria', updatedAt: 1, nome: 'Salute', colore: '#f0708a', visibile: true, ordine: 2 },
        { id: 'cat-uni', type: 'categoria', updatedAt: 1, nome: 'Uni', colore: '#e9a23b', visibile: true, ordine: 3 },
    ];
}
const Stato = (() => {
    const rec = new Map();
    const TIPI_SERVIZIO = new Set(['notifica']);
    const lapideScaduta = (r) => TIPI_SERVIZIO.has(r.type) && (r.updatedAt || 0) < Date.now() - 7 * 86400000;
    const inCorso = new Set();
    const traccia = (p) => { const q = p.catch(e => { console.warn('DB.salva', e); }); inCorso.add(q); q.then(() => inCorso.delete(q)); return q; };
    let ver = 0, cacheVer = -1;
    const perTipo = new Map();
    const ascoltatori = [];
    let inAttesa = false;
    function notifica() {
        if (inAttesa)
            return;
        inAttesa = true;
        Promise.resolve().then(() => { inAttesa = false; ascoltatori.forEach(f => f()); });
    }
    return {
        rec,
        ascolta(f) { ascoltatori.push(f); },
        notifica,
        async carica() {
            for (const r of await DB.apri())
                rec.set(r.id, r);
            ver++;
            if (!rec.has('impostazioni')) {
                const nuovi = predefiniti();
                for (const r of nuovi)
                    if (!rec.has(r.id))
                        rec.set(r.id, r);
                ver++;
                await DB.salva(nuovi);
            }
        },
        tutti(type) {
            if (cacheVer !== ver) {
                perTipo.clear();
                cacheVer = ver;
            }
            let l = perTipo.get(type);
            if (!l) {
                l = [];
                rec.forEach(r => { if (r.type === type && !r.deleted)
                    l.push(r); });
                perTipo.set(type, l);
            }
            return l.slice();
        },
        pulisci() {
            const via = [];
            rec.forEach(r => { if (r.deleted && lapideScaduta(r))
                via.push(r.id); });
            for (const id of via)
                rec.delete(id);
            if (via.length) {
                ver++;
                DB.rimuovi(via);
                if (typeof Drive !== 'undefined')
                    Drive.programma();
            }
            return via.length;
        },
        get ver() { return ver; },
        esiste(id) { return rec.has(id); },
        prendi(id) {
            const r = rec.get(id);
            return r && !r.deleted ? r : undefined;
        },
        salva(r, silenzioso = false) {
            r.updatedAt = Date.now();
            try {
                const em = JSON.parse(localStorage.getItem('imc-email') || '""');
                if (em)
                    r.acc = String(em).toLowerCase();
            }
            catch (_) { }
            rec.set(r.id, r);
            ver++;
            const p = traccia(DB.salva([r]));
            if (!silenzioso)
                notifica();
            if (typeof Drive !== 'undefined')
                Drive.programma();
            if (typeof GCal !== 'undefined' && (r.type === 'evento' || r.type === 'task'))
                GCal.programma();
            return p;
        },
        scritto() { return Promise.all(Array.from(inCorso)).then(() => undefined); },
        elimina(id) {
            const r = rec.get(id);
            if (!r)
                return;
            r.deleted = true;
            this.salva(r);
        },
        unisci(esterni) {
            const cambiati = [];
            for (const e of esterni) {
                if (!e || !e.id || !e.type)
                    continue;
                if (e.deleted && lapideScaduta(e) && !rec.has(e.id))
                    continue;
                const mio = rec.get(e.id);
                const m = mio && e.type === 'statq' && mio.type === 'statq' ? StatQC.unisci(mio, e) : null;
                if (m) {
                    if (!StatQC.uguali(m, mio)) {
                        rec.set(e.id, m);
                        cambiati.push(m);
                        ver++;
                    }
                    continue;
                }
                if (!mio || (e.updatedAt || 0) > (mio.updatedAt || 0)) {
                    rec.set(e.id, e);
                    cambiati.push(e);
                    ver++;
                }
            }
            if (cambiati.length) {
                traccia(DB.salva(cambiati));
                notifica();
            }
            return cambiati.length;
        },
        esporta() { return Array.from(rec.values()); },
        async svuotaLocale() { const ids = Array.from(rec.keys()); rec.clear(); const p = predefiniti(); for (const r of p)
            rec.set(r.id, r); ver++; await DB.rimuovi(ids); await DB.salva(p); notifica(); },
        async togliLocale(ids) { for (const id of ids)
            rec.delete(id); ver++; await DB.rimuovi(ids); notifica(); },
    };
})();
const StatQC = {
    conti(r) { if (!r.c)
        r.c = { legacy: { n: r.n || 0, ok: r.ok || 0, xn: 0, xok: 0 } }; return r.c; },
    mio(r, dev) { const c = StatQC.conti(r); return c[dev] || (c[dev] = { n: 0, ok: 0, xn: 0, xok: 0 }); },
    ricalcola(r) {
        let n = 0, ok = 0;
        for (const k in r.c || {}) {
            const x = r.c[k];
            n += (x.n || 0) - (x.xn || 0);
            ok += (x.ok || 0) - (x.xok || 0);
        }
        r.n = Math.max(0, n);
        r.ok = Math.max(0, Math.min(ok, r.n));
    },
    canon(x) { return x && typeof x === 'object' && !Array.isArray(x) ? Object.keys(x).sort().reduce((o, k) => { o[k] = StatQC.canon(x[k]); return o; }, {}) : x; },
    uguali(a, b) { return JSON.stringify(StatQC.canon(a)) === JSON.stringify(StatQC.canon(b)); },
    unisci(a, b) {
        if (!a.c || !b.c || a.deleted || b.deleted)
            return null;
        const chiave = (r) => JSON.stringify(StatQC.canon([r.ultima || '', !!r.esito, r.scelte || null, r.sk || '']));
        const vince = (a.updatedAt || 0) !== (b.updatedAt || 0) ? ((a.updatedAt || 0) > (b.updatedAt || 0) ? a : b) : (chiave(a) >= chiave(b) ? a : b);
        const c = {};
        for (const k of Array.from(new Set(Object.keys(a.c).concat(Object.keys(b.c)))).sort()) {
            const x = a.c[k] || {}, y = b.c[k] || {}, m = (f) => Math.max(x[f] || 0, y[f] || 0);
            c[k] = { n: m('n'), ok: m('ok'), xn: m('xn'), xok: m('xok') };
        }
        const r = { ...vince, c, updatedAt: Math.max(a.updatedAt || 0, b.updatedAt || 0) };
        StatQC.ricalcola(r);
        return r;
    },
};
