            const nome = SIMBOLI[m[1]];
            if (nome) {
                const ic = icona(nome, 18);
                ic.classList.add('sim');
                fr.appendChild(ic);
                if (m[0].length > m[1].length && m.index + m[0].length < v.length)
                    fr.appendChild(document.createTextNode(' '));
            }
            ultimo = m.index + m[0].length;
