                    continue;
                const priv = privata(t.categoriaId);
                metti({ chiave: 'task:' + t.id + ':' + t.scadenza, at: daDt(t.scadenza).getTime(), titolo: priv ? 'Promemoria' : t.titolo, testo: 'Scade adesso', tag: 'ballot_box_with_check' });
