            return [{ b, da: 0, nome: 'lezione.' + ((b.type.split('/')[1] || 'm4a').split(';')[0].replace('mpeg', 'mp3').replace('x-m4a', 'm4a')) }];
        const Ctx = window.OfflineAudioContext || window.webkitOfflineAudioContext;
