            if (m) {
                const v = m[1].trim().toLowerCase();
                sep = v === 'tab' ? '\t' : v === 'comma' ? ',' : v === 'semicolon' ? ';' : v === 'pipe' ? '|' : v.length === 1 ? v : sep;
            }
            const t = /^#tags column:(\d+)/i.exec(r.trim());
