        return { voci: ps.map((j, k) => ({ ...b, id: ps.length > 1 ? b.id + '#' + (k + 1) : b.id, tipo: ImportaParti.classifica(j), step: ImportaParti.stepDi(j), json: j })), lettura: r.lettura };
